import sys, json, re

d = json.load(sys.stdin)
msgs = d.get("messages", [])
question = ""
for m in msgs:
    if m.get("origin") == "user":
        question = m.get("text", "")
        break

BILLING = {"invoice", "refund", "payment", "bill", "charge", "subscription"}
TECH    = {"error",   "bug",    "crash",   "install", "login", "password"}

def tokenize(text):
    return set(t for t in re.split(r'[^a-z0-9]+', text.lower()) if t)

tokens = tokenize(question)
billing_score = len(tokens & BILLING)
tech_score    = len(tokens & TECH)

# higher score wins; tie (including both 0) → billing (deterministic)
agent_target = "tech" if tech_score > billing_score else "billing"

out = {
    "header": {
        "agent_target": agent_target
    },
    "messages": msgs
}
sys.stdout.write(json.dumps(out))
